// FUNCTION: BFME2 0x0053DF0A size=628 name=?updateContextMultiSelect@ControlBar@@IAEXXZ evidence=N:ledger tier=B hypothesis:Z
void ControlBar::updateContextMultiSelect()
{
	Drawable *draw;
	Object *obj;
	const CommandButton *command;
	GameWindow *win = 0;
	int objectsThatCanDoCommand[32];
	int i;

	// a single drawable evaluates through the command context
	if (m_currentSelectedDrawable != 0)
	{
		updateContextCommand();
		return;
	}

	// zero the array that counts how many objects can do each command
	memset(objectsThatCanDoCommand, 0, sizeof(objectsThatCanDoCommand));

	// get the list of drawables from the in game UI
	const _STL::list<Drawable *> *selectedDrawables = TheInGameUI->getAllSelectedDrawables();

	// loop through all the selected drawables
	for (_STL::list<Drawable *>::const_iterator it = selectedDrawables->begin(); it != selectedDrawables->end(); ++it)
	{
		draw = *it;

		if (draw->getObject()->getTemplate()->isKindOf(KINDOF_IGNORED_IN_GUI)) // ignore these guys
			continue;

		// get the object
		obj = draw->getObject();

		// sanity
		if (obj == 0)
			continue;

		// for each of the visible command windows make sure the object can execute the command
		for (i = 0; i < 32; i++)
		{
			// get the control window
			win = m_commandWindows[i];
			if (!win)
				continue;

			// don't consider hidden windows
			if (win->winIsHidden() == true)
				continue;

			// get the command
			command = (const CommandButton *)GadgetButtonGetData(win);
			if (command == 0)
				continue;

			// can we do the command
			float percent;
			int availability = (int)getCommandAvailability(command, win, obj, &percent, false);

			win->winClearStatus(0x00400000);
			win->winClearStatus(0x01000000);
			win->winClearStatus(0x40000000);
			win->winClearStatus(0x80000000);

			// enable/disable the window control
			GadgetButtonSetDisallowed(win, false);
			int color = 0;
			switch (availability)
			{
				case 3:
					win->winHide(true);
					break;

				case 0:
				case 4:
				case 8:
					win->winEnable(false);
					win->winSetStatus(0x80000000);
					if (availability == 4)
						GadgetButtonSetDisallowed(win, true);
					if (availability == 8)
						win->winSetStatus(0x01000000);
					break;

				case 5:
					color = m_buildUpClockColor;
					win->winEnable(false);
					win->winSetStatus(0x00400000);
					break;

				case 6:
				case 7:
					win->winEnable(false);
					win->winSetStatus(0x01000000);
					break;

				default:
					win->winEnable(true);
					break;
			}

			if (percent < 1.0f)
				Rva003284B9(win, (int)(percent * 100.0f), color);

			// if the button is a CHECK_LIKE, then update its status now
			if ((command->getOptions() & 0x400) != 0)
				GadgetCheckLikeButtonSetVisualCheck(win, availability == 2);

			if (availability == 1 || availability == 2)
				objectsThatCanDoCommand[i]++;
		}
	}

	// for each command, if any objects can do the command we enable the window, otherwise we disable it
	for (i = 0; i < 32; i++)
	{
		win = m_commandWindows[i];
		if (!win)
			continue;

		// don't consider hidden commands
		if (win->winIsHidden() == true)
			continue;

		// don't consider slots that don't have commands
		if (m_commonCommands[i] == 0)
			continue;

		if (objectsThatCanDoCommand[i] > 0)
		{
			win->winEnable(true);
			win->winClearStatus(0x80000000);
			win->winClearStatus(0x01000000);
		}
		else
			win->winEnable(false);
	}
}
